#include <vector>
#include <complex>
#include <algorithm>
#include <cmath>
#include <omp.h>

void sortComplexByMagnitude(std::vector<std::complex<double>> &x) {
    const std::size_t n = x.size();
    if (n < 2) return;

    // Parallel stable merge sort:
    // 1) Each thread sorts its chunk (by magnitude)
    // 2) Iteratively merge adjacent sorted runs; merges are independent and parallelizable
    auto mag2 = [](const std::complex<double>& z) -> double {
        // squared magnitude avoids sqrt, preserves ordering
        const double a = z.real();
        const double b = z.imag();
        return a * a + b * b;
    };

    int T = omp_get_max_threads();
    if (T < 1) T = 1;
    if (static_cast<std::size_t>(T) > n) T = static_cast<int>(n);

    std::vector<std::complex<double>> tmp(n);

    // Determine chunk boundaries
    std::vector<std::size_t> bounds(static_cast<std::size_t>(T) + 1, 0);
    for (int t = 0; t <= T; ++t) {
        bounds[static_cast<std::size_t>(t)] = (n * static_cast<std::size_t>(t)) / static_cast<std::size_t>(T);
    }

    // Local sorts
#pragma omp parallel num_threads(T)
    {
        const int tid = omp_get_thread_num();
        const std::size_t lo = bounds[static_cast<std::size_t>(tid)];
        const std::size_t hi = bounds[static_cast<std::size_t>(tid + 1)];

        std::stable_sort(x.begin() + static_cast<std::ptrdiff_t>(lo),
                         x.begin() + static_cast<std::ptrdiff_t>(hi),
                         [&](const std::complex<double>& a, const std::complex<double>& b) {
                             return mag2(a) < mag2(b);
                         });
    }

    bool in_x = true; // true: current data in x, false: in tmp

    // Iterative merging of runs of size 'width'
    for (std::size_t width = n / static_cast<std::size_t>(T); width < n; width *= 2) {
        // If initial width is 0 due to integer division when T==n, fix it:
        if (width == 0) width = 1;

        if (in_x) {
#pragma omp parallel for schedule(static) num_threads(T)
            for (std::ptrdiff_t i = 0; i < static_cast<std::ptrdiff_t>(n); i += static_cast<std::ptrdiff_t>(2 * width)) {
                const std::size_t left  = static_cast<std::size_t>(i);
                const std::size_t mid   = std::min(left + width, n);
                const std::size_t right = std::min(left + 2 * width, n);

                std::merge(x.begin() + static_cast<std::ptrdiff_t>(left),
                           x.begin() + static_cast<std::ptrdiff_t>(mid),
                           x.begin() + static_cast<std::ptrdiff_t>(mid),
                           x.begin() + static_cast<std::ptrdiff_t>(right),
                           tmp.begin() + static_cast<std::ptrdiff_t>(left),
                           [&](const std::complex<double>& a, const std::complex<double>& b) {
                               return mag2(a) < mag2(b);
                           });
            }
        } else {
#pragma omp parallel for schedule(static) num_threads(T)
            for (std::ptrdiff_t i = 0; i < static_cast<std::ptrdiff_t>(n); i += static_cast<std::ptrdiff_t>(2 * width)) {
                const std::size_t left  = static_cast<std::size_t>(i);
                const std::size_t mid   = std::min(left + width, n);
                const std::size_t right = std::min(left + 2 * width, n);

                std::merge(tmp.begin() + static_cast<std::ptrdiff_t>(left),
                           tmp.begin() + static_cast<std::ptrdiff_t>(mid),
                           tmp.begin() + static_cast<std::ptrdiff_t>(mid),
                           tmp.begin() + static_cast<std::ptrdiff_t>(right),
                           x.begin() + static_cast<std::ptrdiff_t>(left),
                           [&](const std::complex<double>& a, const std::complex<double>& b) {
                               return mag2(a) < mag2(b);
                           });
            }
        }

        in_x = !in_x;
    }

    // If the final sorted data ended up in tmp, copy back to x
    if (!in_x) {
#pragma omp parallel for schedule(static) num_threads(T)
        for (std::ptrdiff_t i = 0; i < static_cast<std::ptrdiff_t>(n); ++i) {
            x[static_cast<std::size_t>(i)] = tmp[static_cast<std::size_t>(i)];
        }
    }
}
